def get_categories():
    return sorted({s["category"] for s in CENTRAL_SCHEMES_CATALOGUE})


def get_catalogue(category: str = ""):
    if not category:
        return CENTRAL_SCHEMES_CATALOGUE
    return [s for s in CENTRAL_SCHEMES_CATALOGUE if s["category"] == category]
